mapper.select:
select id from tb_address_book 

    and school_id = #{schoolId}
    and compus_id = #{compusId}
    and build_category_id = #{buildCategoryId}
    and building_id = #{buildingId}
    and details like concat("%", #{details}, "%") 
    and label = #{label}
    and user_id = #{userId}
    and is_default = #{isDefault}
    and deleted = #{deleted}
